export const cruiseMarkup = "\n\n<div class=\"switch\">\n  <button class=\"on\" id=\"tabChrBtn\" onclick=\"showView('chr')\">Cruise</button>\n  <button id=\"tabCalcBtn\" onclick=\"showView('calc')\">ROI Calculator</button>\n  <button id=\"tabRefBtn\" onclick=\"showView('ref')\">About Cruise</button>\n  <a class=\"nav-demo\" href=\"https://www.intugine.com/schedule-demo\" target=\"_blank\" rel=\"noopener\">Book a Demo \u2192</a>\n</div>\n\n<!-- ============ CRUISE (newspaper) ============ -->\n<div id=\"chronicle\" class=\"sheet\">\n<div class=\"pad\">\n\n  <div class=\"masthead\">\n    <div class=\"pre\">\n      <span class=\"est\"><img id=\"mlogo\" alt=\"\">Est. MMXXVI \u00b7 India Edition</span>\n      <span>AI Control Tower</span>\n      <span id=\"dateline\">\u2014</span>\n    </div>\n    <div class=\"title\">Cruise</div>\n    <div class=\"subhead\">The Autonomous Control Tower \u00b7 All the logistics that's fit to track</div>\n    <div class=\"rule-row\">\n      <span>Vol. I \u00b7 No. 1</span>\n      <span><span class=\"live-dot\"></span>Live from the Control Tower</span>\n      <span id=\"clock\">\u2014</span>\n    </div>\n  </div>\n\n  <div class=\"lead\">\n    <div class=\"lead-text\">\n      <span class=\"kicker\">Front Page \u00b7 Autonomous Operations</span>\n      <h1>The Control Room Sleeps. The Tower Does Not.</h1>\n      <div class=\"deck\">Cruise, Intugine's AI control tower, resolves exceptions overnight \u2014 calling drivers in their own tongue while the desk is dark.</div>\n      <div class=\"byline\">By the Operations Desk \u00b7 Filed 03:00 IST \u00b7 Pictured: a live network</div>\n      <div class=\"cols\">\n        <p class=\"dropcap\">For a decade, the logistics industry chased a single dream: to see every truck. It succeeded. GPS, SIM, FASTag and sensors now render the network visible to the minute. Yet visibility, it turns out, was only half the story.</p>\n        <p>Seeing an exception and resolving one are different labours. The second still fell to humans \u2014 coordinators dialling drivers, deciphering a halt, typing a remark \u2014 until now.</p>\n        <p>Cruise carries each exception the full distance: detect, diagnose, call, log, escalate. Its agents work the night desk without fatigue, in seven tongues, across thousands of simultaneous trips.</p>\n        <p>The picture to the right is not a diagram. It is the network, live \u2014 a truck halts, Cruise calls, the matter resolves, and the wheels turn again. Unaided.</p>\n      </div>\n    </div>\n\n    <div class=\"lead-art\">\n      <div class=\"photo\">\n        <span class=\"tag\">Live \u00b7 Network Desk</span>\n        <svg id=\"flow\" viewBox=\"0 0 480 470\" aria-label=\"How Cruise resolves an exception\"></svg>\n        <div class=\"frame-cap\"><span>Fig. 1 \u2014 How Cruise carries one exception to resolution</span><span id=\"resolvedCount\">0 resolved</span></div>\n      </div>\n\n      <div class=\"photo callbox\">\n        <span class=\"tag\">Live \u00b7 Calling Desk</span>\n        <div class=\"call-screen\">\n          <div class=\"call-head\"><span></span>\n            <span class=\"call-status\"><span class=\"cs-dot\"></span><span id=\"callLang\">\u0939\u093f\u0928\u094d\u0926\u0940</span></span></div>\n          <div id=\"callLines\"></div>\n          <span class=\"stamp\" id=\"callStamp\">\u2713 Resolved \u00b7 logged</span>\n        </div>\n        <div class=\"frame-cap\"><span id=\"callTitle\">Fig. 2 \u2014 An L1 exception handled without a coordinator</span><span id=\"callTimer\">\u2248 90 sec</span></div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ticker-wrap\"><div class=\"ticker\" id=\"tick\"></div></div>\n\n  <!-- product video newsreel -->\n  <div class=\"newsreel\" id=\"newsreel\">\n    <div class=\"nr-head\"><span class=\"l\">\u25c9 Newsreel \u00b7 Cruise in Motion</span><span class=\"r\">Watch \u00b7 2 min</span></div>\n    <div class=\"nr-frame\">\n      <iframe src=\"https://www.youtube.com/embed/wFgR6Cl3f4w\" title=\"Cruise \u2014 AI Control Tower\" loading=\"lazy\"\n        allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" allowfullscreen></iframe>\n    </div>\n    <div class=\"nr-cap\"><span>Film \u2014 The autonomous control tower at work</span><span>Intugine</span></div>\n  </div>\n\n  <!-- AGENTS feature -->\n  <div class=\"agents\">\n    <div class=\"agent\">\n      <div class=\"agent-head\">\n        <img class=\"agent-port\" alt=\"Vedika\" src=\"data:image/jpeg;base64,\">\n        <div><h3>Vedika</h3><div class=\"role\">Communication Agent \u00b7 Night Desk</div>\n          <div class=\"quote\">\"At 3am, in Hindi, I make the call no one else will.\"</div></div>\n      </div>\n      <p>Vedika dials the driver the instant an exception is confirmed \u2014 in Hindi, Marathi, Tamil, Telugu, Kannada, Bhojpuri or Gujarati. She names the reason, captures the resolution timeline, transcribes the reply, updates the ticket, and escalates the moment a line stays silent. No coordinator picks up a phone for an L1 exception again.</p>\n      <ul><li>Halt verification</li><li>ETA confirmation</li><li>Route-deviation checks</li><li>Tracking-gap follow-up</li><li>Hub-dwell follow-up</li><li>Back-unloading detection</li></ul>\n    </div>\n    <div class=\"agent\">\n      <div class=\"agent-head\">\n        <img class=\"agent-port\" alt=\"Ved\" src=\"data:image/jpeg;base64,\">\n        <div><h3>Ved</h3><div class=\"role\">Intelligence Agent \u00b7 Reads the Network</div>\n          <div class=\"quote\">\"One late truck is noise. Three on a lane is a pattern.\"</div></div>\n      </div>\n      <p>Ved watches the whole board. He classifies every exception by severity, scores breach risk, and reads the corridor for pattern \u2014 naming whether trouble is transporter-specific, route-specific or a recurring bottleneck. When risk builds, he predicts the SLA breach three to four hours ahead and tells the team whether to escalate, reroute, or review.</p>\n      <ul><li>P1/P2/P3 triage</li><li>Halt-severity scoring</li><li>Transporter analytics</li><li>SLA breach foresight</li><li>Next-best-action</li><li>Pattern detection</li></ul>\n    </div>\n  </div>\n\n  <!-- lower: how it works -->\n  <div class=\"lower\">\n    <div class=\"col\">\n      <h4>Four Layers, One Motion</h4>\n      <div class=\"sub\">Detect \u00b7 Diagnose \u00b7 Resolve \u00b7 Execute</div>\n      <p><strong>Detect.</strong> Every trip watched against contextual baselines \u2014 a rest-stop halt at 2am reads differently from an industrial-zone halt at 11pm.</p>\n      <p><strong>Diagnose.</strong> The RCA layer names the probable cause \u2014 a breakdown from a back-unloading, a SIM failure from deliberate suppression \u2014 before a single call is placed.</p>\n      <p><strong>Resolve &amp; Execute.</strong> Self-resolve, call, escalate or notify \u2014 then act, without waiting for a coordinator.</p>\n    </div>\n    <div class=\"col\">\n      <h4>Editorial</h4>\n      <div class=\"sub\">On the Coordination Tax</div>\n      <p>Every large shipper now keeps a standing army whose sole task is to relay information between a screen and a driver. It scales with freight, caps growth, and produces nothing a machine could not.</p>\n      <p>The next decade of logistics belongs to systems that <em>act</em>, not merely alert. The newspaper that only reports yesterday is a museum piece \u2014 so, soon, is the tower that only watches.</p>\n      <p style=\"text-align:right;font-style:italic;font-family:var(--serif)\">\u2014 The Editors</p>\n    </div>\n    <div class=\"col\">\n      <h4>By the Numbers</h4>\n      <div class=\"sub\">Verified at Deployment</div>\n      <p><strong>85%+</strong> of exceptions resolved with no coordinator.<br><strong>&lt;5 min</strong> to first contact after detection.<br><strong>70%</strong> less manpower on exception ops.<br><strong>24\u00d77</strong> coverage \u2014 nothing missed overnight.<br><strong>3\u20134 hrs</strong> of SLA-breach foresight.<br><strong>7</strong> regional languages spoken.</p>\n      <p style=\"font-family:var(--cond);text-transform:uppercase;letter-spacing:.08em;font-size:11px\">See the ROI Calculator tab to run your own numbers.</p>\n    </div>\n  </div>\n\n  <!-- IntuTrack 2.0 -->\n  <div class=\"feature\">\n    <div>\n      <span class=\"kicker\">The Companion Story \u00b7 Infrastructure</span>\n      <h3 style=\"font-family:var(--serif);font-weight:900;font-size:32px;line-height:1.0;margin:11px 0 7px\">IntuTrack 2.0: The Wire Service Beneath the Tower</h3>\n      <div class=\"deck\">A control tower is only as sharp as the signal it acts on. IntuTrack 2.0 is the rebuilt ground-truth layer feeding Cruise.</div>\n      <p style=\"font-size:13.5px;text-align:justify\">The upgraded tracking spine fuses GPS from 300-plus vendor integrations with SIM-based location, FASTag reads and activity sensing \u2014 holding a continuous, ground-truth picture even when any single source drops out. Where older systems blinked, IntuTrack 2.0 keeps the line. It is the wire service; Cruise is the editor that acts on every dispatch.</p>\n      <div class=\"chips\"><span>300+ GPS integrations</span><span>SIM tracking</span><span>FASTag fusion</span><span>Activity sensing</span><span>Signal failover</span><span>Ground-truth visibility</span></div>\n    </div>\n    <div class=\"signalbox\">\n      <span class=\"tag\" style=\"position:static;display:block;width:max-content;margin:9px 9px 0\">Live \u00b7 Signal Fusion</span>\n      <svg id=\"fusion\" viewBox=\"0 0 300 200\" style=\"margin-top:4px\"><rect width=\"300\" height=\"200\" fill=\"#FAF8F2\"/></svg>\n      <div class=\"frame-cap\"><span>Fig. 3 \u2014 Four signals, one truth</span><span id=\"fusionState\">nominal</span></div>\n    </div>\n  </div>\n\n  <!-- demo CTA -->\n  <div class=\"cta\">\n    <div class=\"cta-txt\">\n      <div class=\"cta-k\">See it on your network</div>\n      <h3>Watch Cruise resolve your exceptions \u2014 live.</h3>\n      <p>Book a 30-minute demo with Intugine's enterprise team and see the tower work on your corridors.</p>\n    </div>\n    <a href=\"https://www.intugine.com/schedule-demo\" target=\"_blank\" rel=\"noopener\">Schedule a Demo \u2192</a>\n  </div>\n\n  <footer class=\"chr\">Cruise \u2014 AI Control Tower \u00b7 Powered by Intugine &amp; IntuTrack 2.0 \u00b7 Trusted by 75+ global enterprises \u00b7 \u00a9 MMXXVI Intugine Technologies</footer>\n</div>\n</div>\n\n<!-- ============ ROI CALCULATOR ============ -->\n<div id=\"calcTab\"><div id=\"calcRoot\">\n\n<section class=\"hero\">\n  <div class=\"wrap\">\n    <div class=\"eyebrow\">ROI Calculator</div>\n    <h1>What would <em>Cruise</em> cost \u2014 and save \u2014 on your network?</h1>\n    <p>Enter your freight numbers. Cruise is priced at a simple \u20b98 per call-minute; see that expressed per trip, per trip-day, per call and per alert, alongside your savings versus running the desk yourself.</p>\n    <div class=\"ticker\" id=\"ticker\"></div>\n  </div>\n</section>\n\n<div class=\"wrap\">\n  <div class=\"grid\">\n\n    <!-- CONTROLS -->\n    <aside class=\"panel\">\n      <h2>Your operation</h2>\n      <div class=\"sub\">Everything updates as you drag.</div>\n\n      <div class=\"grp\">\n        <div class=\"grp-label\">Freight volume</div>\n        <div class=\"field\"><div class=\"row\"><label>Trips per month</label><span class=\"val\" id=\"v_trips\"></span></div>\n          <input type=\"range\" id=\"trips\" min=\"1000\" max=\"60000\" step=\"1000\" value=\"20000\"></div>\n        <div class=\"field\"><div class=\"row\"><label>Average trip duration</label><span class=\"val unit\" id=\"v_days\" data-unit=\"days\"></span></div>\n          <input type=\"range\" id=\"days\" min=\"1\" max=\"10\" step=\"0.5\" value=\"2.5\"></div>\n      </div>\n\n      <div class=\"grp\">\n        <div class=\"grp-label\">Alerts, calls &amp; minutes</div>\n        <div class=\"field\"><div class=\"row\"><label>Alerts per trip</label><span class=\"val\" id=\"v_apt\"></span></div>\n          <input type=\"range\" id=\"apt\" min=\"0.5\" max=\"12\" step=\"0.05\" value=\"5.85\"></div>\n        <div class=\"field\"><div class=\"row\"><label>Calls per alert</label><span class=\"val\" id=\"v_cpa\"></span></div>\n          <input type=\"range\" id=\"cpa\" min=\"1\" max=\"3\" step=\"0.1\" value=\"1\"></div>\n        <div class=\"field\"><div class=\"row\"><label>Minutes per call</label><span class=\"val unit\" id=\"v_mpc\" data-unit=\"min\"></span></div>\n          <input type=\"range\" id=\"mpc\" min=\"0.5\" max=\"6\" step=\"0.5\" value=\"1.5\"></div>\n      </div>\n\n      <div class=\"grp\">\n        <div class=\"grp-label\">Cruise price</div>\n        <div class=\"field\"><div class=\"row\"><label>Price per call-minute</label><span class=\"val unit\" id=\"v_rate\" data-unit=\"\u20b9\"></span></div>\n          <input type=\"range\" id=\"rate\" min=\"4\" max=\"15\" step=\"0.5\" value=\"8\"></div>\n        <div class=\"pricehint\" id=\"pricehint\"></div>\n      </div>\n\n      <div class=\"grp\">\n        <div class=\"grp-label\">Your current calling team</div>\n        <div class=\"field\"><div class=\"row\"><label>First-level callers</label><span class=\"val\" id=\"v_ppl\"></span></div>\n          <input type=\"range\" id=\"ppl\" min=\"0\" max=\"120\" step=\"1\" value=\"36\"></div>\n        <div class=\"field\"><div class=\"row\"><label>Salary / caller / month <span class=\"lblnote\">(incl. infra &amp; welfare)</span></label><span class=\"val unit\" id=\"v_sal\" data-unit=\"\u20b9\"></span></div>\n          <input type=\"range\" id=\"sal\" min=\"12000\" max=\"90000\" step=\"1000\" value=\"30000\"></div>\n        <div class=\"field\"><div class=\"row\"><label>Other cost per call <span class=\"lblnote\">(infra, calling, misc)</span></label><span class=\"val unit\" id=\"v_other\" data-unit=\"\u20b9\"></span></div>\n          <input type=\"range\" id=\"other\" min=\"0\" max=\"5\" step=\"0.25\" value=\"1\"></div>\n        <div class=\"field\"><div class=\"row\"><label>Callers per supervisor</label><span class=\"val\" id=\"v_span\"></span></div>\n          <input type=\"range\" id=\"span\" min=\"4\" max=\"15\" step=\"1\" value=\"8\"></div>\n        <div class=\"field\"><div class=\"row\"><label>Salary / supervisor / month</label><span class=\"val unit\" id=\"v_supsal\" data-unit=\"\u20b9\"></span></div>\n          <input type=\"range\" id=\"supsal\" min=\"25000\" max=\"120000\" step=\"5000\" value=\"45000\"></div>\n        <div class=\"field\"><div class=\"row\"><label>Training cost / new hire</label><span class=\"val unit\" id=\"v_train\" data-unit=\"\u20b9\"></span></div>\n          <input type=\"range\" id=\"train\" min=\"0\" max=\"60000\" step=\"2500\" value=\"15000\"></div>\n        <div class=\"field\"><div class=\"row\"><label>Annual attrition rate</label><span class=\"val unit\" id=\"v_attr\" data-unit=\"%\"></span></div>\n          <input type=\"range\" id=\"attr\" min=\"0\" max=\"100\" step=\"5\" value=\"50\"></div>\n      </div>\n\n      <div class=\"grp\">\n        <div class=\"grp-label\">Loss avoidance \u2014 Detention / demurrage</div>\n        <div class=\"field\"><div class=\"row\"><label>Events per 100 trips</label><span class=\"val\" id=\"v_c0\"></span></div>\n          <input type=\"range\" id=\"c0\" min=\"0\" max=\"40\" step=\"1\" value=\"18\"></div>\n        <div class=\"field\"><div class=\"row\"><label>\u20b9 cost per event</label><span class=\"val unit\" id=\"v_k0\" data-unit=\"\u20b9\"></span></div>\n          <input type=\"range\" id=\"k0\" min=\"0\" max=\"20000\" step=\"500\" value=\"3500\"></div>\n        <div class=\"field\"><div class=\"row\"><label>Cruise prevention %</label><span class=\"val unit\" id=\"v_p0\" data-unit=\"%\"></span></div>\n          <input type=\"range\" id=\"p0\" min=\"0\" max=\"100\" step=\"5\" value=\"45\"></div>\n      </div>\n\n      <div class=\"grp\">\n        <div class=\"grp-label\">Loss avoidance \u2014 Vehicle idle / turnaround</div>\n        <div class=\"field\"><div class=\"row\"><label>Events per 100 trips</label><span class=\"val\" id=\"v_c1\"></span></div>\n          <input type=\"range\" id=\"c1\" min=\"0\" max=\"40\" step=\"1\" value=\"22\"></div>\n        <div class=\"field\"><div class=\"row\"><label>\u20b9 cost per event</label><span class=\"val unit\" id=\"v_k1\" data-unit=\"\u20b9\"></span></div>\n          <input type=\"range\" id=\"k1\" min=\"0\" max=\"20000\" step=\"500\" value=\"2200\"></div>\n        <div class=\"field\"><div class=\"row\"><label>Cruise prevention %</label><span class=\"val unit\" id=\"v_p1\" data-unit=\"%\"></span></div>\n          <input type=\"range\" id=\"p1\" min=\"0\" max=\"100\" step=\"5\" value=\"40\"></div>\n      </div>\n\n      <div class=\"grp\">\n        <div class=\"grp-label\">Loss avoidance \u2014 Delivery SLA penalty</div>\n        <div class=\"field\"><div class=\"row\"><label>Events per 100 trips</label><span class=\"val\" id=\"v_c2\"></span></div>\n          <input type=\"range\" id=\"c2\" min=\"0\" max=\"40\" step=\"1\" value=\"10\"></div>\n        <div class=\"field\"><div class=\"row\"><label>\u20b9 cost per event</label><span class=\"val unit\" id=\"v_k2\" data-unit=\"\u20b9\"></span></div>\n          <input type=\"range\" id=\"k2\" min=\"0\" max=\"30000\" step=\"500\" value=\"8000\"></div>\n        <div class=\"field\"><div class=\"row\"><label>Cruise prevention %</label><span class=\"val unit\" id=\"v_p2\" data-unit=\"%\"></span></div>\n          <input type=\"range\" id=\"p2s\" min=\"0\" max=\"100\" step=\"5\" value=\"35\"></div>\n      </div>\n\n      <div class=\"grp\">\n        <div class=\"grp-label\">Loss avoidance \u2014 Back-unloading / mis-delivery</div>\n        <div class=\"field\"><div class=\"row\"><label>Events per 100 trips</label><span class=\"val\" id=\"v_c3\"></span></div>\n          <input type=\"range\" id=\"c3\" min=\"0\" max=\"40\" step=\"1\" value=\"4\"></div>\n        <div class=\"field\"><div class=\"row\"><label>\u20b9 cost per event</label><span class=\"val unit\" id=\"v_k3\" data-unit=\"\u20b9\"></span></div>\n          <input type=\"range\" id=\"k3\" min=\"0\" max=\"40000\" step=\"1000\" value=\"12000\"></div>\n        <div class=\"field\"><div class=\"row\"><label>Cruise prevention %</label><span class=\"val unit\" id=\"v_p3\" data-unit=\"%\"></span></div>\n          <input type=\"range\" id=\"p3\" min=\"0\" max=\"100\" step=\"5\" value=\"55\"></div>\n      </div>\n    </aside>\n\n    <!-- RESULTS -->\n    <main class=\"results\">\n\n      <div class=\"verdict\" id=\"verdict\">\n        <div class=\"lab\">Your return \u2014 hard savings + loss avoided</div>\n        <div class=\"big\" id=\"roiBig\">\u2014</div>\n        <div class=\"note\" id=\"roiNote\">\u2014</div>\n      </div>\n\n      <!-- PRICE in every unit -->\n      <div class=\"priceblock\">\n        <div class=\"pb-head\"><h3>Cruise price, every way you'd quote it</h3><span class=\"pill\" id=\"pbMonthly\">\u2014</span></div>\n        <div class=\"pb-grid\">\n          <div class=\"pb-cell\"><div class=\"pl\">Per minute</div><div class=\"pv\" id=\"pMin\">\u2014</div></div>\n          <div class=\"pb-cell\"><div class=\"pl\">Per call</div><div class=\"pv\" id=\"pCall\">\u2014</div></div>\n          <div class=\"pb-cell\"><div class=\"pl\">Per alert</div><div class=\"pv\" id=\"pAlert\">\u2014</div></div>\n          <div class=\"pb-cell\"><div class=\"pl\">Per trip</div><div class=\"pv\" id=\"pTrip\">\u2014</div></div>\n          <div class=\"pb-cell\"><div class=\"pl\">Per trip-day</div><div class=\"pv\" id=\"pTripDay\">\u2014</div></div>\n          <div class=\"pb-cell\"><div class=\"pl\">Per year</div><div class=\"pv\" id=\"pYear\">\u2014</div></div>\n        </div>\n      </div>\n\n      <!-- CURRENT team cost in every unit -->\n      <div class=\"priceblock\" style=\"margin-top:20px\">\n        <div class=\"pb-head\"><h3>Your current cost, the same way</h3><span class=\"pill\" id=\"cbMonthly\">\u2014</span></div>\n        <div class=\"pb-grid\">\n          <div class=\"pb-cell\"><div class=\"pl\">Per minute</div><div class=\"pv\" id=\"cMin\">\u2014</div></div>\n          <div class=\"pb-cell\"><div class=\"pl\">Per call</div><div class=\"pv\" id=\"cCall\">\u2014</div></div>\n          <div class=\"pb-cell\"><div class=\"pl\">Per alert</div><div class=\"pv\" id=\"cAlert\">\u2014</div></div>\n          <div class=\"pb-cell\"><div class=\"pl\">Per trip</div><div class=\"pv\" id=\"cTrip\">\u2014</div></div>\n          <div class=\"pb-cell\"><div class=\"pl\">Per trip-day</div><div class=\"pv\" id=\"cTripDay\">\u2014</div></div>\n          <div class=\"pb-cell\"><div class=\"pl\">Per year</div><div class=\"pv\" id=\"cYear\">\u2014</div></div>\n        </div>\n        <div class=\"losshint\" style=\"padding:0 14px 12px\">Fully-loaded: caller salaries (incl. infra &amp; welfare) + other per-call cost + supervisors + training/attrition.</div>\n      </div>\n\n      <div class=\"cards\">\n        <div class=\"card\"><div class=\"lab\">Your team today</div><div class=\"num\" id=\"cHuman\">\u2014</div><div class=\"sub\">fully-loaded / month</div></div>\n        <div class=\"card\"><div class=\"lab\">Cruise</div><div class=\"num orange\" id=\"cPrice\">\u2014</div><div class=\"sub\">all-in / month</div></div>\n        <div class=\"card\"><div class=\"lab\">You save</div><div class=\"num green\" id=\"cSave\">\u2014</div><div class=\"sub\">net / month, hard + avoided</div></div>\n      </div>\n\n      <!-- HUMAN vs AI -->\n      <div class=\"versus\">\n        <div class=\"vh\"><h3>Your control room vs Cruise</h3><span class=\"pill\">at your volume</span></div>\n        <div class=\"vrow head\"><div class=\"m\">Metric</div><div class=\"h\">Your team</div><div class=\"a\">Cruise</div></div>\n        <div class=\"vrow\"><div class=\"m\">People employed (callers + supervisors)</div><div class=\"h bad\" id=\"hPeople\">\u2014</div><div class=\"a\">0</div></div>\n        <div class=\"vrow\"><div class=\"m\">Calls handled / month (capacity)</div><div class=\"h\" id=\"hCalls\">\u2014</div><div class=\"a\" id=\"aCalls\">\u2014</div></div>\n        <div class=\"vrow\"><div class=\"m\">Concurrent calls at a spike</div><div class=\"h bad\" id=\"hConc\">\u2014</div><div class=\"a\">Unlimited</div></div>\n        <div class=\"vrow\"><div class=\"m\">Response to a new alert</div><div class=\"h bad\">Queues</div><div class=\"a\">&lt; 5 min</div></div>\n        <div class=\"vrow\"><div class=\"m\">Coverage</div><div class=\"h bad\">Shifts + gaps</div><div class=\"a\">24\u00d77\u00d7365</div></div>\n        <div class=\"vrow\"><div class=\"m\">Regional languages</div><div class=\"h bad\">Per-agent skill</div><div class=\"a\">7+ built-in</div></div>\n        <div class=\"vrow\"><div class=\"m\">Fully-loaded monthly cost</div><div class=\"h bad\" id=\"hCost\">\u2014</div><div class=\"a\" id=\"aCost\">\u2014</div></div>\n        <div class=\"qual\">\n          <div id=\"q1\"></div><div id=\"q2\"></div><div id=\"q3\"></div><div id=\"q4\"></div>\n        </div>\n      </div>\n\n      <!-- POOL 2 breakdown -->\n      <div class=\"versus\">\n        <div class=\"vh\"><h3>Proactive loss avoided</h3><span class=\"pill\" id=\"p2Total\">\u2014</span></div>\n        <div class=\"vrow head\"><div class=\"m\">Cost Cruise prevents</div><div class=\"h\">/ month</div><div class=\"a\">/ year</div></div>\n        <div class=\"vrow\"><div class=\"m\">Detention / demurrage</div><div class=\"h\" id=\"l0m\">\u2014</div><div class=\"a\" id=\"l0y\">\u2014</div></div>\n        <div class=\"vrow\"><div class=\"m\">Vehicle idle / turnaround loss</div><div class=\"h\" id=\"l1m\">\u2014</div><div class=\"a\" id=\"l1y\">\u2014</div></div>\n        <div class=\"vrow\"><div class=\"m\">Delivery SLA penalty</div><div class=\"h\" id=\"l2m\">\u2014</div><div class=\"a\" id=\"l2y\">\u2014</div></div>\n        <div class=\"vrow\"><div class=\"m\">Back-unloading / mis-delivery</div><div class=\"h\" id=\"l3m\">\u2014</div><div class=\"a\" id=\"l3y\">\u2014</div></div>\n      </div>\n\n      <div class=\"cards\">\n        <div class=\"card\"><div class=\"lab\">Pool 1 \u00b7 hard savings</div><div class=\"num\" id=\"cPool1\">\u2014</div><div class=\"sub\">replacing the calling team</div></div>\n        <div class=\"card\"><div class=\"lab\">Pool 2 \u00b7 loss avoided</div><div class=\"num\" id=\"cPool2\">\u2014</div><div class=\"sub\">problems prevented early</div></div>\n        <div class=\"card\"><div class=\"lab\">Blended ROI</div><div class=\"num orange\" id=\"cROI\">\u2014</div><div class=\"sub\">value \u00f7 Cruise price</div></div>\n      </div>\n\n      <p class=\"disclaimer\">Illustrative model. Pool 1 is the fully-loaded cost of running your own calling team (salaries + supervisors + attrition). Pool 2 is expected-value loss avoidance across detention, idle time, SLA penalties and back-unloading \u2014 benchmark rates shown, fully editable in the spreadsheet. Cruise pricing shown at \u20b9<span id=\"dRate\">8</span>/minute.</p>\n\n    </main>\n  </div>\n\n  <div class=\"cta\" style=\"margin:0 24px 40px\">\n    <div class=\"cta-txt\">\n      <div class=\"cta-k\">Like what the numbers say?</div>\n      <h3>Put these savings to the test on your own freight.</h3>\n      <p>Book a 30-minute demo and we'll model Cruise against your real exception volume.</p>\n    </div>\n    <a href=\"https://www.intugine.com/schedule-demo\" target=\"_blank\" rel=\"noopener\">Schedule a Demo \u2192</a>\n  </div>\n</div>\n\n<footer>\n  <div class=\"wrap\">Cruise \u2014 AI Control Tower \u00b7 Intugine Technologies \u00b7 Pricing at \u20b98 / call-minute\n  <div class=\"disclaimer\" style=\"margin:6px auto 0\">Figures recalculated live from your inputs. For a board-ready model with full loss-avoidance categories and every pricing basis, use the spreadsheet model.</div></div>\n</footer>\n\n</div></div>\n\n<!-- ============ REFERENCE ============ -->\n<div id=\"reference\" class=\"sheet\"><div class=\"pad\">\n  <h1>Cruise\u2122 \u2014 AI Control Tower</h1>\n  <p class=\"lede\">Intugine's AI-powered logistics control tower \u2014 autonomous exception detection, AI calling in regional languages, escalation management, and operational intelligence for Indian enterprise logistics.</p>\n  <h2>What is Cruise\u2122?</h2>\n  <p>Cruise\u2122 moves enterprises from passive visibility to active exception resolution. It continuously monitors every active shipment, detects operational exceptions in real time, initiates AI-powered calls to drivers and transporters in regional languages, captures responses, logs every action, and escalates only the cases that require human judgement. Traditional control towers help teams see what is happening; Cruise helps teams act on it.</p>\n  <h2>Meet Vedika &amp; Ved</h2>\n  <p><strong>Vedika \u2014 Communication Agent.</strong> Calls drivers and transporters the moment an exception is confirmed, in their preferred regional language. Identifies the reason, captures the resolution timeline, transcribes the response, updates the ticket, and triggers escalation if unanswered.</p>\n  <p><strong>Ved \u2014 Intelligence Agent.</strong> Classifies exceptions by severity (P1/P2/P3), detects ETA breach risk, scores halt severity, analyses transporter performance, and surfaces next-best-action recommendations.</p>\n  <h2>Core Capabilities</h2>\n  <ul>\n    <li><strong>Exception detection, 98%+ coverage</strong> \u2014 route deviations, halts, ETA breaches, reverse movement, geofence breaches, idling, tracking gaps, missed milestones, e-way bill expiry, tamper alerts.</li>\n    <li><strong>AI calling in regional languages</strong> \u2014 responses transcribed, structured and logged automatically; no coordinator needed for L1 exceptions.</li>\n    <li><strong>Intelligent escalation matrix</strong> \u2014 retry, then fleet manager, then transporter desk, on time-based triggers, fully logged.</li>\n    <li><strong>Predictive SLA breach detection</strong> \u2014 flags risk 3\u20134 hours ahead using lane-level history and corridor delay models.</li>\n    <li><strong>Multi-modal signal fusion</strong> \u2014 GPS (300+ integrations), SIM, FASTag and activity sensing combined for continuous ground truth.</li>\n    <li><strong>Role-based views</strong> \u2014 for operations, management, transporters and client teams.</li>\n  </ul>\n  <h2>Core Metrics</h2>\n  <ul><li>15,000+ trips monitored daily</li><li>&lt;5 minutes average response after exception detection</li><li>98%+ exceptions identified</li><li>24\u00d77 monitoring \u2014 zero missed overnight exceptions</li><li>85%+ task success rate on AI-agent calls</li><li>70% reduction in exception-operations manpower</li></ul>\n  <h2>Deployment Timeline</h2>\n  <ul><li><strong>Day 1</strong> \u2014 GPS vehicles auto-discovered; market vehicles via SIM; pre-reporting visibility active.</li><li><strong>Week 1</strong> \u2014 exception matrix configured; AI calling activated for P1/P2.</li><li><strong>Weeks 2\u20134</strong> \u2014 lane thresholds tuned, hub dwell configured, SLA windows set.</li><li><strong>Month 2+</strong> \u2014 analytics layer active: transporter scorecards, exception trends, SLA dashboards.</li></ul>\n</div></div>\n\n\n\n<!-- embedded calculator script -->\n\n";
